-- serves: WHERE tenant_id = ? AND created_at > ? ORDER BY created_at
CREATE INDEX idx_orders_tenant_created ON orders (tenant_id, created_at);
EXPLAIN ANALYZE SELECT * FROM orders
WHERE tenant_id = 42 AND created_at > now() - interval '7 days';
-- want: Index Scan using idx_orders_tenant_created, not Seq Scan on orders

-- hot path: dashboard totals answered entirely from the index
CREATE INDEX idx_orders_cover
  ON orders (tenant_id, status) INCLUDE (total_cents);
SELECT status, count(*), sum(total_cents)
FROM orders WHERE tenant_id = 42 GROUP BY status;
-- plan shows: Index Only Scan (heap fetches only while pages are not all-visible)

// pool budget: (db_cores * 2) divided across replicas
const pool = new Pool({
  max: 10,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000, // fail fast when saturated
});

-- every code path transfers in the same ID order, so no cycle forms
UPDATE accounts SET balance = balance - $amt
WHERE id = least($from, $to);
UPDATE accounts SET balance = balance + $amt
WHERE id = greatest($from, $to);
-- wrap in one transaction; on deadlock (SQLSTATE 40P01) retry with backoff

-- tenancy enforced by the engine, not by every query
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON orders
  USING (tenant_id = current_setting('app.tenant_id')::uuid);
SET app.tenant_id = '0f1e2d3c-4b5a-6789-abcd-ef0123456789'; -- per request
SELECT count(*) FROM orders; -- silently scoped to that tenant
